{
    const PREFIX = 'GXModules/c1zz/StandaloneBlog/';
    private $root;
    private $package;
    private $embedded;

    public function __construct($root, array $package, $embedded = null)
    {
        $this->root = realpath($root);
        $this->package = $package;
        $this->embedded = $embedded;
        if (!$this->root || !isset($package['version'], $package['archive'], $package['archive_sha256'], $package['files'])
            || !is_string($package['version']) || !preg_match('/\A\d+\.\d+\.\d+\z/', $package['version'])
            || (isset($package['installer']) && $package['installer'] !== 'c1zz-blog-install-'.$package['version'].'.php')
            || $package['archive'] !== 'c1zz-standalone-blog-' . $package['version'] . '.zip'
            || !is_string($package['archive_sha256']) || !preg_match('/\A[a-f0-9]{64}\z/', $package['archive_sha256'])
            || !is_array($package['files']) || count($package['files']) < 1 || count($package['files']) > 1000) {
            throw new RuntimeException('package_invalid');
        }
    }

    public function inspect()
    {
