                || !hash_equals($this->package['archive_sha256'], hash('sha256', $this->embedded))) { throw new RuntimeException('zip_changed'); }
            $temporary = tmpfile();
            if (!$temporary) { throw new RuntimeException('private_temp_required'); }
            $file = stream_get_meta_data($temporary)['uri'];
            $publicRoots = [$this->root];
            if (!empty($_SERVER['DOCUMENT_ROOT']) && realpath($_SERVER['DOCUMENT_ROOT'])) { $publicRoots[] = realpath($_SERVER['DOCUMENT_ROOT']); }
            foreach ($publicRoots as $publicRoot) {
                if (strpos(realpath($file), rtrim($publicRoot, '/') . '/') === 0) {
                    fclose($temporary); throw new RuntimeException('private_temp_required');
                }
            }
            if (fwrite($temporary, $this->embedded) !== strlen($this->embedded)) { fclose($temporary); throw new RuntimeException('paths_failed'); }
        } else {
            if (is_link($file) || !is_file($file) || !is_readable($file)) { throw new RuntimeException('zip_missing'); }
            if (filesize($file) > 8388608 || !hash_equals($this->package['archive_sha256'], hash_file('sha256', $file))) { throw new RuntimeException('zip_changed'); }
        }
        $zip = new ZipArchive();
        if ($zip->open($file) !== true) { if ($temporary) { fclose($temporary); } throw new RuntimeException('package_invalid'); }
        $contents = [];
        $expected = [];
        $total = 0;
        try {
            foreach ($this->package['files'] as $entry) {
                if (!isset($entry['path'], $entry['bytes'], $entry['sha256']) || !is_string($entry['path'])
                    || strpos($entry['path'], self::PREFIX) !== 0 || !is_int($entry['bytes'])
                    || $entry['bytes'] < 0 || $entry['bytes'] > 10485760 || !is_string($entry['sha256'])
                    || !preg_match('/\A[a-f0-9]{64}\z/', $entry['sha256'])) { throw new RuntimeException('package_invalid'); }
                $relative = substr($entry['path'], strlen(self::PREFIX));
                if (!preg_match('/\A(?:[a-zA-Z0-9_-][a-zA-Z0-9_.-]*\/)*[a-zA-Z0-9_-][a-zA-Z0-9_.-]*\z/', $relative)
                    || isset($expected[strtolower($entry['path'])])) { throw new RuntimeException('package_invalid'); }
                $expected[strtolower($entry['path'])] = $entry;
                $total += $entry['bytes'];
            }
            if ($total > 16777216 || $zip->numFiles !== count($expected)) { throw new RuntimeException('package_invalid'); }
            foreach (range(0, $zip->numFiles - 1) as $index) {
                $info = $zip->statIndex($index);
                $name = $info['name'];
                $entry = $expected[strtolower($name)] ?? null;
                $zip->getExternalAttributesIndex($index, $system, $attributes);
                if (!$entry || $entry['path'] !== $name || isset($contents[$name])
                    || (($attributes >> 16) & 0170000) === 0120000 || $info['size'] !== $entry['bytes']) {
                    throw new RuntimeException('package_invalid');
                }
                $data = $zip->getFromIndex($index, $entry['bytes'] + 1);
                if (!is_string($data) || strlen($data) !== $entry['bytes']
                    || !hash_equals($entry['sha256'], hash('sha256', $data))) { throw new RuntimeException('package_invalid'); }
                $contents[$name] = $data;
            }
        } finally { $zip->close(); if ($temporary) { fclose($temporary); } }
        return $contents;
    }

    public function preflight($script)
    {
        if ($script !== $this->root . '/' . ($this->package['installer'] ?? 'c1zz-blog-install.php') || is_link($script) || !is_file($script)
            || !is_writable($this->root) || !is_readable($this->root)) { throw new RuntimeException('cleanup_permissions'); }
        foreach (['cache', 'cache/smarty', 'GXModules', 'GXModules/c1zz', 'GXModules/c1zz/StandaloneBlog'] as $relative) {
            $path = $this->root . '/' . $relative;
            if (is_link($path) || (file_exists($path) && (!is_dir($path) || !is_writable($path)))) { throw new RuntimeException('paths_failed'); }
        }
        if (!is_dir($this->root . '/cache') || !is_dir($this->root . '/GXModules')) { throw new RuntimeException('paths_failed'); }
        return count($this->inspect());
    }

    public function apply()
    {
        $cache = $this->root . '/cache';
        $gx = $this->root . '/GXModules';
        $vendor = $gx . '/c1zz';
        $target = $vendor . '/StandaloneBlog';
        foreach ([$cache, $gx, $vendor, $target] as $path) {
            if (is_link($path) || (file_exists($path) && !is_dir($path))) { throw new RuntimeException('path_invalid'); }
        }
        if (!is_dir($cache) || !is_writable($cache) || !is_dir($gx)
            || !is_writable(is_dir($vendor) ? $vendor : $gx)) { throw new RuntimeException('paths_failed'); }
        $lockPath = $cache . '/c1zz-blog-package.lock';
        if (is_link($lockPath)) { throw new RuntimeException('path_invalid'); }
        $lock = fopen($lockPath, 'c');
        if (!$lock || !flock($lock, LOCK_EX | LOCK_NB)) { if ($lock) { fclose($lock); } throw new RuntimeException('package_busy'); }
        chmod($lockPath, 0600);
