                if(response.status!==401){throw new Error('probe');}
                if(running){
                    if(popup&&popup.closed){stop('Das Anmeldefenster wurde geschlossen. Bei Bedarf erneut öffnen.');}
                    else if(Date.now()>expires){stop('Die Wartezeit ist abgelaufen. Bitte die Anmeldung erneut öffnen.');}
                    else{timer=setTimeout(check,1500);}
                }
            }).catch(function(){if(running){stop('Die Anmeldung konnte nicht geprüft werden. Bitte „Anmeldung abgeschlossen – weiter“ wählen oder erneut anmelden.');}})
            .then(function(){busy=false;clearTimeout(timeout);});
    }
    link.addEventListener('click',function(event){
        event.preventDefault();
        if(popup&&!popup.closed){popup.focus();return;}
        popup=window.open(link.href,'c1zzBlogAdminLogin'+Math.random().toString(36).slice(2),'popup,width=600,height=760');
        if(!popup){stop('Das Anmeldefenster wurde blockiert. Den Link in einem neuen Tab öffnen, danach hier „Anmeldung abgeschlossen – weiter“ wählen.');return;}
        running=true;expires=Date.now()+600000;status.textContent='Auf die Admin-Anmeldung warten …';clearTimeout(timer);
        timer=setTimeout(check,300);
    });
    check();
}());
