        $c1zzOldName = basename($c1zzOldZip);
        $c1zzOldHash = $c1zzRootPackage['legacy_archives'][$c1zzOldName] ?? null;
        if (count($c1zzLegacy) >= 30 || !is_string($c1zzOldHash) || is_link($c1zzOldZip)
            || !is_file($c1zzOldZip) || !hash_equals($c1zzOldHash, hash_file('sha256', $c1zzOldZip))) { throw new RuntimeException('legacy_zip_unknown'); }
        $c1zzLegacy[$c1zzOldName] = $c1zzOldHash;
    }
    $c1zzLegacyInstallers=[];
    $c1zzInstallerFiles=glob($c1zzRoot.'/c1zz-blog-install-*.php');
    if(file_exists($c1zzRoot.'/c1zz-blog-install.php')||is_link($c1zzRoot.'/c1zz-blog-install.php')){$c1zzInstallerFiles[]=$c1zzRoot.'/c1zz-blog-install.php';}
    foreach($c1zzInstallerFiles as$c1zzOldInstaller){
        $c1zzOldName=basename($c1zzOldInstaller);if($c1zzOldName===$c1zzScriptName){continue;}
        $c1zzOldHash=$c1zzRootPackage['legacy_installers'][$c1zzOldName] ?? null;
        if(count($c1zzLegacyInstallers)>=30||!is_string($c1zzOldHash)||is_link($c1zzOldInstaller)||!is_file($c1zzOldInstaller)
            ||!hash_equals($c1zzOldHash,hash_file('sha256',$c1zzOldInstaller))){throw new RuntimeException('legacy_installer_unknown');}
        $c1zzLegacyInstallers[$c1zzOldName]=$c1zzOldHash;
