        $c1zzToken = $_POST['pageToken'] ?? null;
        $c1zzForm = $_SESSION['c1zz_blog_root_form'] ?? [];
        if (!is_string($c1zzToken) || !preg_match('/\A[a-f0-9]{32}\z/', $c1zzToken)
            || !is_string($_POST['rootToken'] ?? null) || !isset($c1zzForm['token'])
            || !hash_equals($c1zzForm['token'], $_POST['rootToken']) || ($c1zzForm['owner'] ?? 0) !== (int)$_SESSION['customer_id']
            || ($c1zzForm['expires'] ?? 0) < time() || ($c1zzForm['package'] ?? '') !== $c1zzRootPackage['archive_sha256']) {
            http_response_code(403); throw new RuntimeException('request_invalid');
        }
        if (!hash_equals($c1zzForm['script_sha256'] ?? '', hash_file('sha256', __FILE__))) {
            http_response_code(403); throw new RuntimeException('request_invalid');
        }
        $c1zzPageToken = $_SESSION['coo_page_token'];
        if (!(method_exists($c1zzPageToken, 'verify') ? $c1zzPageToken->verify($c1zzToken, false) : $c1zzPageToken->is_valid($c1zzToken))) {
            http_response_code(403); throw new RuntimeException('request_invalid');
        }
