            if (!$c1zzDone) { throw new RuntimeException('request_invalid'); }
            require_once $c1zzRoot . '/GXModules/c1zz/StandaloneBlog/Classes/BlogInstallerUploads.php';
            \C1zz\StandaloneBlog\BlogInstallerUploads::cleanup($c1zzRoot,
                ['operation'=>'install','owner'=>(int)$_SESSION['customer_id'],'package_version'=>$c1zzRootPackage['version']],
                ['owner'=>(int)$_SESSION['customer_id'],'version'=>$c1zzRootPackage['version'],'expires'=>time()+60,
                    'script_sha256'=>$c1zzForm['script_sha256'],'script_name'=>$c1zzScriptName,'legacy_archives'=>$c1zzLegacy,'legacy_installers'=>$c1zzLegacyInstallers]);
            unset($_SESSION['c1zz_blog_root_form'], $_SESSION['c1zz_blog_installer_upload'], $_SESSION['c1zz_blog_auto_start']);
            header('Location: ' . DIR_WS_ADMIN . 'admin.php?do=C1zzBlogAdmin', true, 303); exit;
