        if (!$c1zzForm['used'] && ($c1zzHasData || $c1zzInstalled) && ($_POST['backup'] ?? '') !== '1') { throw new RuntimeException('backup_required'); }
        $c1zzInitialSlug='';
        if (!$c1zzHasData && !$c1zzInstalled) {
            $c1zzInitialSlug=$_POST['blog_slug'] ?? 'blog';
            if (!is_string($c1zzInitialSlug) || strlen($c1zzInitialSlug)>80 || !preg_match('/\A[a-z0-9]+(?:-[a-z0-9]+)*\z/',$c1zzInitialSlug) || preg_match('/\A[a-z]{2}\z/',$c1zzInitialSlug)) { throw new RuntimeException('blog_address_invalid'); }
        }
        if (!$c1zzForm['used']) {
            $c1zzBackend->preflight(__FILE__);
