        $_SESSION['c1zz_blog_installer_upload'] = ['owner'=>(int)$_SESSION['customer_id'],
            'version'=>$c1zzRootPackage['version'],'expires'=>time()+7200,
            'script_sha256'=>$c1zzForm['script_sha256'],'script_name'=>$c1zzScriptName,'legacy_archives'=>$c1zzLegacy,'legacy_installers'=>$c1zzLegacyInstallers];
        $_SESSION['c1zz_blog_auto_start'] = ['owner'=>(int)$_SESSION['customer_id'],
            'version'=>$c1zzRootPackage['version'],'expires'=>time()+1800,'slug'=>$c1zzInitialSlug];
        // Native discovery only on explicit POST. New code loads in the following request.
        if (empty($_SESSION['c1zz_blog_root_form']['prepared'])) {
            MainFactory::create('CacheControl')->clear_data_cache(); GXModulesCache::getFiles();
            // The first new wizard page must not render an older compiled setup template.
