$c1zzHeadings = ['install' => 'Blog neu installieren', 'update' => 'Blog aktualisieren', 'reinstall' => 'Blog wieder aktivieren', 'check' => 'Blog ist bereits aktuell'];
$c1zzForm = ['token' => bin2hex(random_bytes(24)), 'owner' => (int)$_SESSION['customer_id'], 'expires' => time() + 1800,
    'package' => $c1zzRootPackage['archive_sha256'], 'script_sha256'=>hash_file('sha256', __FILE__), 'used' => false];
